<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {ElMessage} from 'element-plus'
import {session,request} from '../session'
import {useData,action,modes,terminals} from '../data'
import {t} from '../i18n'
import {formatDate} from '../api'
import Softphone from '../components/Softphone.vue'
const calls=useData('/api/v1/calls?page=1&size=20'),queue=useData('/api/v1/handoffs?state=waiting'),presence=ref(session.user?.agent_status||'ready'),saving=ref(false),presenceError=ref(false),busy=ref(false),model=ref({mode:'human_only',max_attempts:1}),form=ref();let wrapHeartbeat;const wrapSeconds=ref(0);let heartbeat
const active=computed(()=>(calls.data.value||[]).filter(v=>!terminals.includes(v.status))),phoneCall=computed(()=>active.value.find(v=>['in_human','handoff_transferring','answered'].includes(v.status))||active.value[0])
async function savePresence(value,notify=true){const previous=presence.value;presence.value=value;saving.value=true;try{const saved=await request('/api/v1/auth/presence','PUT',{status:value});presence.value=saved.agent_status;presenceError.value=false;return true}catch(error){presence.value=previous;presenceError.value=true;if(notify)ElMessage.error(error.message||t('presenceUpdateFailed'));return false}finally{saving.value=false}}
function refresh(){calls.load();queue.load()}
async function dial(){busy.value=true;try{await action(()=>request('/api/v1/calls','POST',model.value),{refresh:calls.load});model.value={mode:'human_only',max_attempts:1}}finally{busy.value=false}}
async function respond(item,kind){await action(()=>request(`/api/v1/calls/${item.call_session_id}/handoffs/${item.id}/${kind}`,'POST'),{confirm:t(kind==='accept'?'confirmAcceptHandoff':'confirmRejectHandoff'),refresh});if(kind==='accept'){presence.value='busy';presenceError.value=false}}
async function handover(call){await action(()=>request('/api/v1/calls/'+call.id+'/handover','POST'),{refresh:calls.load});await savePresence('busy')}
onMounted(()=>{if(session.user?.role==='agent'){heartbeat=setInterval(()=>savePresence(presence.value,false),30000);wrapHeartbeat=setInterval(async()=>{try{const conf=await request('/api/v1/ops/workspace');const previous=wrapSeconds.value;wrapSeconds.value=conf.remaining_seconds||0;if(wrapSeconds.value>0&&presence.value!=='offline')presence.value='busy';else if(previous>0&&presence.value==='busy')await savePresence('ready',false)}catch{}},5000)}})
onUnmounted(()=>{clearInterval(heartbeat);clearInterval(wrapHeartbeat)})
</script><template><PageHeader title="workspace" description="workbenchHint"/><el-alert v-if="presenceError" type="error" :title="t('presenceUpdateFailed')" :description="t('presenceUpdateFailedHint')"><el-button @click="savePresence(presence)">{{t('retry')}}</el-button></el-alert><el-alert v-if="wrapSeconds>0" :title="'通话后整理，剩余 '+wrapSeconds+' 秒'" type="info"/><div class="split"><section><Softphone :active-call="phoneCall" @registered="savePresence('ready',false)" @update="refresh"/><el-card :header="t('callNow')"><FieldForm ref="form" :model="model" :fields="[{key:'phone',label:'phone',required:true,pattern:/^\+?[0-9 ()-]{6,32}$/,message:t('invalidPhone')},{key:'mode',label:'mode',options:modes},{key:'max_attempts',label:'attempts',type:'number',min:1,max:10}]" hide-submit @submit="dial"/><el-button type="primary" :loading="busy" :disabled="presence!=='ready'" @click="form.submit()">{{t('callNow')}}</el-button></el-card><el-card :header="t('profile')"><el-descriptions :column="1"><el-descriptions-item :label="t('contactName')">{{session.user?.full_name}}</el-descriptions-item><el-descriptions-item :label="t('username')">{{session.user?.username}}</el-descriptions-item><el-descriptions-item :label="t('agentStatus')"><el-select :model-value="presence" :loading="saving" :disabled="saving" aria-label="座席状态" @change="savePresence"><el-option v-for="value in ['ready','busy','offline']" :key="value" :value="value" :label="t('agent'+value[0].toUpperCase()+value.slice(1))"/></el-select></el-descriptions-item></el-descriptions></el-card></section><section><el-card :header="t('handoffQueue')"><el-button @click="queue.load">{{t('refresh')}}</el-button><el-alert v-if="queue.error.value" type="error" :title="queue.error.value"/><div v-for="item in queue.data.value||[]" :key="item.id" class="record-card"><div class="actions"><strong>{{item.contact_name||t('unknownCustomer')}}</strong><span>{{item.phone||item.call_session_id}}</span><el-tag>{{t('waiting_human')}}</el-tag></div><p>{{item.campaign_name||t('noCampaign')}} · {{t(item.mode||'unknown')}} · {{t('waitedSeconds',{count:item.wait_seconds||0})}}</p><p v-if="item.intent">{{t('intent')}}：{{item.intent}}</p><p v-if="item.last_customer_utterance">{{t('lastCustomerUtterance')}}：{{item.last_customer_utterance}}</p><p v-if="item.summary">{{t('summary')}}：{{item.summary}}</p><div class="actions"><el-button type="primary" :disabled="presence!=='ready'" @click="respond(item,'accept')">{{t('accept')}}</el-button><el-button type="danger" @click="respond(item,'reject')">{{t('reject')}}</el-button></div></div><el-empty v-if="!queue.data.value?.length" :description="t('empty')"/></el-card><el-card :header="t('activeQueue')"><el-button @click="calls.load">{{t('refresh')}}</el-button><el-alert v-if="calls.error.value" type="error" :title="calls.error.value"/><div v-for="call in active" :key="call.id" class="record-card"><strong>{{call.phone}}</strong> <el-tag>{{t(call.status)}}</el-tag><p>{{t('mode')}}：{{t(call.mode)}} · {{formatDate(call.updated_at)}}</p><el-button :disabled="presence!=='ready'||!['dialing','answered','in_ai','waiting_human'].includes(call.status)" @click="handover(call)">{{t('handoff')}}</el-button></div><el-empty v-if="!active.length" :description="t('empty')"/></el-card></section></div></template>
